select jsonb_build_object(
'observed_at',clock_timestamp(),
'migrations',(select count(*) from supabase_migrations.schema_migrations),
'bot',(select jsonb_build_object('bot_id',bot_id,'mode',mode,'enabled',enabled) from telegram_private.transport_bots where bot_id='100142513132091'),
'events',(select jsonb_agg(jsonb_build_object('id',id,'state',state,'attempts',attempts,'delivery_attempts',delivery_attempts,'error_code',error_code,'has_input',payload_ciphertext is not null,'has_output',result_ciphertext is not null,'lease_live',lease_until>clock_timestamp()) order by sequence) from telegram_private.transport_events where bot_id='100142513132091'),
'subjects',(select jsonb_agg(jsonb_build_object('user_id',p.user_id,'financial_details',(select jsonb_agg(jsonb_build_object('id',t.id,'kind',t.kind,'status',t.status,'amount_minor',(t.amount*100)::numeric(20,0)::text,'request_id',t.create_request_id,'entry_sum_minor',(select (sum(e.signed_amount)*100)::numeric(20,0)::text from finance.transaction_entries e where e.user_id=t.user_id and e.transaction_id=t.id),'confirmation_count',(select count(*) from telegram_private.confirmations c where c.user_id=t.user_id and c.result->>'movementId'=t.id::text)) order by t.id) from finance.transactions t where t.user_id=p.user_id),'transactions',(select count(*) from finance.transactions where user_id=p.user_id),'entries',(select count(*) from finance.transaction_entries where user_id=p.user_id),'events',(select count(*) from finance.transaction_events where user_id=p.user_id),'drafts',(select count(*) from telegram_private.drafts where user_id=p.user_id),'confirmations',(select count(*) from telegram_private.confirmations where user_id=p.user_id),'links',(select count(*) from telegram_private.links where user_id=p.user_id),'accounts',(select jsonb_agg(jsonb_build_object('id',a.id,'currency',a.currency_code,'balance_minor',((a.opening_balance+coalesce((select sum(e.signed_amount) from finance.transaction_entries e join finance.transactions t on t.id=e.transaction_id and t.user_id=e.user_id where e.user_id=a.user_id and e.account_id=a.id and t.status='posted'),0))*100)::numeric(20,0)::text)) from finance.accounts a where a.user_id=p.user_id)) order by p.user_id) from finance.profiles p where p.user_id in ('a1ae8770-cb52-4f66-bbef-c5783cb46b2c','d73e11ac-6d8a-4fb6-bbc5-dc83367dcf82')),
'functions',(select jsonb_agg(jsonb_build_object('oid',p.oid,'owner',p.proowner,'acl',p.proacl,'definer',p.prosecdef,'config',p.proconfig,'signature',p.oid::regprocedure::text,'source',md5(replace(p.prosrc,chr(13)||chr(10),chr(10)))) order by p.oid) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('api','finance','ops','telegram_private')),
'unsafe_tenant_tables',(select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('finance','ops','telegram_private') and c.relkind='r' and c.relname<>'currencies' and (not c.relrowsecurity or not c.relforcerowsecurity))
) as audit;